            self.process.start()
            self.miner_log = "Starting Cryptocurrency Mining..."

    def stop_mining(self):
        if self.process:
            self.process.join(timeout=5)  # Allow up to 5 seconds for the thread to terminate.
            self.miner_log = "Cryptocurrency mining stopped."

